// === Tab: mySketch ===
let angleX = 0;
let angleY = 0;
let noiseOffset = 0;

// Halftone settings
let dotSize = 8; // Size of the grid
let dotDensity = 50; // How many dots across

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();
}

function draw() {
  background(245, 240, 235); // Paper color

  // Update rotation and morphing
  angleX += 0.01;
  angleY += 0.015;
  noiseOffset += 0.01; // Makes the shape "breath"

  translate(width / 2, height / 2);

  // Riso Blend Mode (Subtracts color like ink)
  blendMode(MULTIPLY);

  // --- LAYER 1: CYAN (Top Left Light) ---
  // We add random() to x/y to simulate "Misregistration" (shaky printer)
  push();
  let shakeC = random(-2, 2); 
  translate(-30 + shakeC, -30 + shakeC); 
  drawHalftoneShadow(color(0, 255, 255), "TOP_LEFT");
  pop();

  // --- LAYER 2: MAGENTA (Top Right Light) ---
  push();
  let shakeM = random(-2, 2);
  translate(30 + shakeM, -20 + shakeM);
  drawHalftoneShadow(color(255, 0, 128), "TOP_RIGHT");
  pop();

  // --- LAYER 3: YELLOW (Bottom Light) ---
  push();
  let shakeY = random(-2, 2);
  translate(0 + shakeY, 40 + shakeY);
  drawHalftoneShadow(color(255, 255, 0), "BOTTOM");
  pop();

  // Reset blend mode
  blendMode(BLEND);

  // Add Paper Grain (Static Noise)
  drawPaperTexture();
}

// --- THE CORE MECHANIC: HALFTONE SHADOWS ---
function drawHalftoneShadow(inkColor, lightPos) {
  fill(inkColor);

  // We scan a grid of points
  for (let x = -150; x <= 150; x += dotSize) {
    for (let y = -150; y <= 150; y += dotSize) {

      // 1. IS THIS POINT INSIDE THE SHADOW?
      // We calculate a "fake" 3D shape using math
      // A morphing sphere/cube hybrid
      let d = dist(0, 0, x, y);

      // Create a wobbly radius using Sin/Cos and Noise
      // This defines the invisible shape's outline
      let rBase = 100;
      let deformation = sin(angleX + x*0.02) * cos(angleY + y*0.02) * 30;
      let noiseVal = noise(x*0.01 + noiseOffset, y*0.01);
      let rLimit = rBase + deformation + (noiseVal * 40);

      // If we are inside the shape...
      if (d < rLimit) {

        // 2. CALCULATE DOT SIZE (Shading)
        // Instead of flat color, we change dot size based on "light"
        let shade = 0;

        // Simple faux-lighting logic
        if (lightPos === "TOP_LEFT") shade = map(x + y, -200, 200, 2, dotSize);
        if (lightPos === "TOP_RIGHT") shade = map(x - y, -200, 200, 2, dotSize);
        if (lightPos === "BOTTOM") shade = map(y, -200, 200, 2, dotSize);

        // Clamp size
        shade = constrain(shade, 1, dotSize * 0.9);

        // Draw the dot
        circle(x, y, shade);
      }
    }
  }
}

// Adds gritty texture on top
function drawPaperTexture() {
  loadPixels();
  // Only affect 10% of pixels for speed
  for (let i = 0; i < width * height * 4; i += 40) {
    // Randomly darken pixels slightly to look like recycled paper
    if (random() > 0.5) {
       let grain = random(-10, 10);
       pixels[i] += grain;
       pixels[i+1] += grain;
       pixels[i+2] += grain;
    }
  }
  updatePixels();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

